"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82251"],{17485(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_regra_padrao_de_outro_fato","status":422,"titulo":"A altera\xe7\xe3o deixaria de valer a regra padr\xe3o de outro fato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_regra_padrao_de_outro_fato","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), mas a regra padr\xe3o de outro fato (um derivado por regra) cita este fato, e a defini\xe7\xe3o nova a deixaria inv\xe1lida, por exemplo ao trocar o tipo de dado de que a condi\xe7\xe3o depende. A recusa considera apenas os problemas causados pela altera\xe7\xe3o: uma regra que j\xe1 era inv\xe1lida antes n\xe3o impede a altera\xe7\xe3o. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159, e a API recusa a altera\xe7\xe3o que deixaria inv\xe1lido algo que j\xe1 cita o fato, em vez de alter\xe1-lo em sil\xeancio. Nada \xe9 gravado: o fato continua com a defini\xe7\xe3o anterior.","A recusa vem na lista `errors` da resposta, com `field` igual a `citacoes.regrasPadrao.<c\xf3digo do fato derivado>`, uma entrada por fato afetado. A mensagem cita o que deixaria de valer."],"comoResolver":["Escolha uma das sa\xeddas. Ajuste a regra padr\xe3o do fato derivado citado, para que ela valha com a defini\xe7\xe3o nova, ou remova dela a condi\xe7\xe3o que cita este fato, e reenvie a altera\xe7\xe3o. Desativar o fato derivado n\xe3o basta, porque a regra dele continua sendo conferida. Se a regra deve continuar como est\xe1, escolha uma defini\xe7\xe3o que a mantenha v\xe1lida.","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);